import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let {t} be a fixed integer with {t} \\ge 2. Consider all positive integers n and all sequences of positive reals {a_1 \\le a_2 \\le \\cdots \\le a_n} satisfying the constraint \\(\\sum_{k=1}^n a_k = \\sum_{k=1}^n \\frac{1}{a_k}\\). Determine, as a function of {t}, the complete set of all positive integers n for which the following inequality holds for every such nondecreasing sequence: \\(\\prod_{k=1}^n a_k^{k^{\\,{t}}} \\ge 1\\). After solving, output the set in the exact format:\n### The final answer is: $\\boxed{\\{<enumerate each n>\\}}$'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose t in {2,3,4,5,6} to ensure strictly harder-than-seed instances
t = rng.randint(2, 6)
return {'t': t}

    def verifier(assign):
# Validate domain constraints and compute the complete set of n satisfying the property.
# Derived characterization: The property holds for all nondecreasing sequences
# with sum constraint if and only if sum_{k=1}^{n-1} k^t <= n^t.
# This follows from extremal analysis: the infimum of the weighted log-product occurs
# along two-level sequences (n-1 equal small terms and one large term), and asymptotics
# as the small term -> 0 give a necessary and sufficient condition.
t = assign.get('t', None)
if t is None:
    # Missing required parameter
    return (False, None)
if not isinstance(t, int):
    return (False, None)
if t < 2:
    # Enforce hardness: t must be >= 2 so the instance is strictly harder than the seed.
    return (False, None)
# Compute n_max such that sum_{k=1}^{n-1} k^t <= n^t
# Because sum of powers grows like n^{t+1}/(t+1), once the inequality fails it will fail for all larger n.
def sum_powers(m, p):
    return sum((k ** p) for k in range(1, m + 1))
valid_ns = []
n = 1
while True:
    # For n=1, sum over empty set is 0 <= 1^t, so n=1 is always valid.
    S = sum_powers(n - 1, t)
    if S <= (n ** t):
        valid_ns.append(n)
        # Guard against unreasonable growth; t>=2 implies the set remains small.
        n += 1
        # To avoid infinite loops in pathological cases, cap n (though mathematically unnecessary for t>=2)
        if n > 1000:
            break
    else:
        break
# Format the answer as an enumerated LaTeX set
enumerated = ", ".join(str(x) for x in valid_ns)
answer = f"### The final answer is: $\\boxed{{\\{{{enumerated}\\}}}}$"
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

